import CoreText
import Foundation

/// Leipzig (SIL OFL, from Verovio) -- the SMuFL music-symbol font that Verovio's SVG
/// text refers to for things like melisma extenders and metronome note values.
enum Leipzig {
    static func font(size: CGFloat) -> CTFont? {
        guard let desc = descriptor else { return nil }
        return CTFontCreateWithFontDescriptor(desc, size, nil)
    }
    private static let descriptor: CTFontDescriptor? = {
        guard let data = Data(base64Encoded: base64) else { return nil }
        return CTFontManagerCreateFontDescriptorFromData(data as CFData)
    }()
    private static let base64 = ""
}
